using LeHoangMy_1381.MyProject.Toeic;
using System;
using Xunit;

namespace LeHoangMy_1381.MyProject.Tests.Toeic;

public class ReadingImageValidatorTests
{
    private const string Jpeg = "";

    [Fact]
    public void Jpeg_requires_a_frame_and_scan_not_only_start_and_end_markers()
    {
        var fake = new byte[16];
        fake[0] = 255; fake[1] = 216; fake[^2] = 255; fake[^1] = 217;
        Assert.Null(ReadingImageValidator.Mime(fake));
    }

    [Fact]
    public void Real_jpeg_is_accepted_but_truncated_segment_with_added_end_marker_is_rejected()
    {
        var valid = Convert.FromBase64String(Jpeg);
        Assert.Equal("image/jpeg", ReadingImageValidator.Mime(valid));
        var truncated = valid[..40]; truncated[^2] = 255; truncated[^1] = 217;
        Assert.Null(ReadingImageValidator.Mime(truncated));
    }
}
